css:
html, body {
    font-size: 9px !important;
    margin: 0 !important;
    padding: 0 !important;
}

@page {
    size: A4 portrait;
    margin: 6mm 6mm 6mm 6mm;
}

.payslip-container {
    border: 2px solid #000;
    padding: 6px;
    font-family: Arial, sans-serif;
    font-size: 9px;
    width: 100%;
    box-sizing: border-box;
}

.print-heading {
    text-align: center;
    margin-bottom: 4px;
    border-bottom: 2px solid #000;
    padding-bottom: 3px;
}

.company-details h2 {
    margin: 0 0 2px 0;
    font-size: 12px;
    font-weight: bold;
    color: #000;
}

.company-details p {
    margin: 0;
    font-size: 9px;
    color: #000;
}

.payslip-title {
    background-color: #e8e8e8;
    text-align: center;
    padding: 3px;
    margin-bottom: 4px;
    border: 1px solid #000;
}

.payslip-title h3 {
    font-size: 10px;
    margin: 0;
    font-weight: bold;
    color: #000;
}

.employee-summary {
    margin-bottom: 4px;
}

.summary-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9px;
    table-layout: fixed;
}

.summary-table .summary-title {
    background-color: #e8e8e8;
    font-weight: bold;
    font-size: 9px;
    padding: 2px 5px;
    text-align: left;
    border-bottom: 2px solid #000;
    color: #000;
}

.summary-table tbody tr {
    line-height: 1.05;
}

.summary-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

.summary-table tbody tr:nth-child(odd) {
    background-color: #fff;
}

.summary-table .label-cell {
    font-weight: 600;
    padding: 1px 5px;
    border: none;
    color: #000;
    font-size: 9px;
    white-space: normal;
    word-break: break-word;
    overflow: visible;
    width: 22%;
}

.summary-table .value-cell {
    padding: 1px 5px;
    border: none;
    color: #333;
    white-space: normal;
    word-break: break-word;
    font-size: 9px;
    width: 28%;
}

.earnings-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 4px;
    table-layout: fixed;
    font-size: 9px;
}

.earnings-table .col-header {
    background-color: #dbeafe;
    padding: 3px;
    border: 1px solid #000;
    font-size: 9px;
    font-weight: bold;
    text-align: center;
    color: #000;
}

.earnings-table .sub-header {
    background-color: #fff;
    padding: 1px 5px;
    border: 1px solid #000;
    font-size: 8px;
    font-weight: normal;
    color: #000;
}

.earnings-table .sub-left  { text-align: left; }
.earnings-table .sub-right { text-align: right; }

.earnings-table .data-label {
    padding: 1px 4px;
    border: 1px solid #000;
    font-size: 9px;
    line-height: 1.1;
    color: #000;
    word-wrap: break-word;
}

.earnings-table .data-value {
    padding: 1px 4px;
    border: 1px solid #000;
    font-size: 9px;
    line-height: 1.1;
    text-align: right;
    color: #000;
    white-space: nowrap;
}

.earnings-table tfoot .total-row {
    background-color: #e8e8e8;
    font-weight: bold;
}

.earnings-table .total-label-cell {
    padding: 2px 4px;
    border: 1px solid #000;
    font-size: 9px;
    font-weight: bold;
    color: #000;
}

.earnings-table .total-value-cell {
    padding: 2px 4px;
    border: 1px solid #000;
    font-size: 9px;
    font-weight: bold;
    text-align: right;
    color: #000;
    white-space: nowrap;
}

.earnings-table .group-label-row {
    background-color: #f3f4f6;
    padding: 1px 4px;
    border: 1px solid #000;
    font-size: 7px;
    font-weight: bold;
    font-style: italic;
    text-align: left;
    color: #374151;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.net-payable-section {
    background-color: #d1fae5;
    padding: 4px;
    text-align: center;
    border: 2px solid #000;
    margin-top: 0;
}

.net-amount {
    font-weight: bold;
    font-size: 10px;
    margin: 0 0 2px 0;
    color: #000;
}

.net-words {
    font-size: 9px;
    margin: 0;
    color: #000;
}

#payslip-loader {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(255, 255, 255, 0.88);
    z-index: 99999;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: Arial, sans-serif;
}

#payslip-loader.active { display: flex; }

.pl-spinner {
    width: 52px;
    height: 52px;
    border: 5px solid #e0e0e0;
    border-top-color: #2563eb;
    border-radius: 50%;
    animation: pl-spin 0.75s linear infinite;
    margin-bottom: 16px;
}

.pl-text {
    font-size: 14px;
    font-weight: 600;
    color: #374151;
    letter-spacing: 0.02em;
}

.pl-sub {
    font-size: 11px;
    color: #9ca3af;
    margin-top: 4px;
}

@keyframes pl-spin { to { transform: rotate(360deg); } }

@media print {
    html, body {
        margin: 0 !important;
        padding: 0 !important;
        font-size: 9px !important;
    }
    .payslip-container {
        border: 2px solid #000;
        padding: 6px;
        page-break-inside: avoid;
    }
    #payslip-loader { display: none !important; }
}
